func TestNearestPicksTheLowestRoundTrip(t *testing.T) {
	t.Parallel()

	from := Region{RTT: map[string]time.Duration{"uk-london-1": 150 * time.Millisecond, "eu-amsterdam-1": 120 * time.Millisecond}}
