func (provider *Provider) now() time.Time {
	if provider.Now != nil {
		return provider.Now().UTC()
	}
	return time.Now().UTC()
}

func (provider *Provider) Local(ctx context.Context) Summary {
	region := strings.ToLower(provider.Cell)
	summary := Summary{Version: summaryVersion, Region: region, Local: true, Reach: decisionlog.RegionOK,
		ObservedAt: provider.now(), TerraBase: TerraBase{Readiness: "unknown",
			ReadinessReason: "current native root task and member readiness source is unavailable"}}
	if provider.LinkProbes != nil {
		summary.Links = provider.LinkProbes()
	}
	if provider.NativeRegion != nil {
		summary.TerraBase.NativeRegion = provider.NativeRegion()
	}
	var cluster *observability.ClusterSnapshot
	if provider.Cluster != nil {
		if snapshot, err := provider.Cluster.Cluster(ctx, false); err == nil {
			cluster = &snapshot
		}
	}
	unobserved := false
	if cluster == nil && provider.Snapshot != nil {
		if snapshot, err := provider.Snapshot.Snapshot(ctx, false); err == nil {
			cluster = &observability.ClusterSnapshot{Cell: snapshot.Cell, Members: []observability.MemberSnapshot{snapshot}}
			// Without a cluster source this member is the whole cell; with
			// one that failed, the rest of the roster is unknown.
			unobserved = provider.Cluster != nil
		}
	}
	if cluster != nil {
		fillFromCluster(&summary, *cluster)
		if unobserved {
			summary.Quorum = Quorum{Answering: summary.Quorum.Answering, Ready: summary.Quorum.Ready, Unobserved: true}
		}
	}
	if provider.History != nil {
		var sum float64
		var count int
		for _, value := range latest(provider.History, observability.HistCPUUtilization) {
			sum += value
			count++
		}
		if count > 0 {
			summary.Capacity.CPUUtilization = sum / float64(count)
		}
	}
	if provider.Decisions != nil {
		limit := cmp.Or(provider.LatestDecisions, DefaultLatestDecisions)
		if result, err := provider.Decisions.Query(ctx, decisionlog.Query{Regions: []string{region}, Limit: limit}); err == nil {
			summary.Decisions = result.Decisions
		}
	}
	var open []insights.Insight
	if provider.Insights != nil {
		// The engine also raises insights about other regions (one that
		// does not answer); they belong to the global view, not this
		// region's counts and score.
		for _, insight := range provider.Insights.Current().Insights {
			if insight.Region == "" || strings.EqualFold(insight.Region, region) {
				open = append(open, insight)
			}
		}
		summary.Counts = insights.Count(open)
		summary.Insights = open[:min(len(open), cmp.Or(provider.TopInsights, DefaultTopInsights))]
	}
	summary.Health = score(summary, cluster != nil, open)
	if provider.Nodes != nil {
		summary.Nodes = provider.Nodes(ctx)
		truncated := len(summary.Nodes) > maxTopologyMembers
		summary.boundNodes()
		for index := range summary.Nodes {
			node := &summary.Nodes[index]
			node.Resources = CollectResources(*node, provider.History, summary.ObservedAt)
		}
		fillNodeCapacity(&summary)
		summary.Capacity.Partial = summary.Capacity.Partial || truncated
		summary.TerraBase.WAN = CollectWAN(summary.Nodes, summary.TerraBase.NativeRegion, provider.History, summary.ObservedAt)
	}
	if provider.Cost != nil {
		summary.Cost = provider.Cost(ctx)
	}
	return summary
}

func fillFromCluster(summary *Summary, cluster observability.ClusterSnapshot) {
	quorum := &summary.Quorum
	quorum.Expected = len(cluster.Expected)
	if quorum.Expected == 0 {
		quorum.Expected = len(cluster.Members) + len(cluster.Missing)
	}
	quorum.Answering = len(cluster.Members)
	quorum.Required = quorum.Expected/2 + 1
	quorum.Missing = slices.Clone(cluster.Missing)
	versions := map[string][]string{}
	for _, member := range cluster.Members {
		if member.Ready {
			quorum.Ready++
		}
		if len(summary.Members) < maxTopologyMembers {
			summary.Members = append(summary.Members, Member{Name: member.Member, Role: member.Role, Ready: member.Ready,
				Version: member.BuildVersion, MetaLeader: member.NATS != nil && member.NATS.IsMetaLeader})
		}
		if member.BuildVersion != "" {
			versions[member.BuildVersion] = append(versions[member.BuildVersion], member.Member)
		}
		// The owner is the newest valid lease any member observes, whatever
		// the member order; the holder's own report wins a tie. A member
		// that observes no ready lease (control-log failures keep its own
		// candidate as OwnerID) is no evidence of a leader.
		if authority := member.Authority; authority != nil && authority.Ready && authority.Epoch > 0 &&
			(authority.Leader || authority.OwnerID != "") {
			owner := authority.OwnerID
			if authority.Leader {
				owner = member.Member
			}
			if authority.Epoch > summary.Leaders.Epoch || authority.Epoch == summary.Leaders.Epoch && authority.Leader {
				summary.Leaders.Authority, summary.Leaders.Epoch = owner, authority.Epoch
			}
		}
		if nats := member.NATS; nats != nil {
			if nats.MetaLeader != "" {
				summary.Leaders.MetaLeader = nats.MetaLeader
			}
			summary.Capacity.StoreUsedBytes += nats.StoreUsedBytes
			summary.Capacity.StoreLimitBytes += nats.StoreLimitBytes
		}
		if system := member.System; system != nil {
			summary.Capacity.CPUs += system.CPUCount
			summary.Capacity.MemoryBytes += system.MemTotalBytes
			summary.Capacity.MemoryUsedBytes += system.MemTotalBytes - min(system.MemAvailBytes, system.MemTotalBytes)
			for _, filesystem := range observability.DistinctFilesystems(system.Filesystems) {
				summary.Capacity.DiskBytes += filesystem.SizeBytes
				summary.Capacity.DiskUsedBytes += filesystem.SizeBytes - min(filesystem.AvailBytes, filesystem.SizeBytes)
			}
		}
	}
	quorum.Healthy = quorum.Answering >= quorum.Required
	for _, version := range slices.Sorted(maps.Keys(versions)) {
		members := versions[version]
		slices.Sort(members)
		summary.Versions = append(summary.Versions, Version{Version: version, Members: members})
	}
	var placement *observability.PlacementView
	for _, member := range cluster.Members {
		if member.Placement != nil && (placement == nil || len(member.Placement.Databases) > len(placement.Databases)) {
			placement = member.Placement
		}
	}
	slices.SortFunc(summary.Members, func(left, right Member) int { return strings.Compare(left.Name, right.Name) })
	if placement != nil {
		// Placement lists one entry per database partition. A terminal
		// partition keeps its historical roster after teardown; it is no
		// longer live, so it counts toward nothing active.
		databases := map[string]bool{}
		for _, database := range placement.Databases {
			if !database.Terminal {
				databases[database.DatabaseID] = true
			}
		}
		summary.TerraBase.Databases = len(databases)
		hosts := map[string]*Host{}
		for _, database := range placement.Databases {
			if database.Terminal {
				continue
			}
			for _, seat := range database.Members {
				if seat.HostNode == "" {
					continue
				}
				host := hosts[seat.HostNode]
				if host == nil {
					host = &Host{Name: seat.HostNode, Readiness: "unknown",
						ReadinessReason: "current native root task and member readiness source is unavailable"}
					hosts[seat.HostNode] = host
				}
				host.Seats++
			}
			summary.TerraBase.DesiredSeats += database.DesiredSeats
			summary.TerraBase.Readiness = "unknown"
			summary.TerraBase.ReadinessReason = "current native root task and member readiness source is unavailable"
			if rollout := database.Rollout; rollout != nil && rollout.Completed < rollout.Seats {
				summary.Rollouts = append(summary.Rollouts, *rollout)
			}
		}
		for _, name := range slices.Sorted(maps.Keys(hosts)) {
			if len(summary.Hosts) == maxTopologyHosts {
				break
			}
			summary.Hosts = append(summary.Hosts, *hosts[name])
		}
	}
}

func score(summary Summary, observed bool, open []insights.Insight) Health {
	if !observed || summary.Quorum.Answering == 0 {
		return Health{Score: 0, Status: StatusUnknown, Reasons: []string{"no member state observed"}}
	}
	value := 100
	var reasons []string
	penalize := func(points int, reason string) {
		value -= points
		reasons = append(reasons, reason)
	}
	quorum := summary.Quorum
	if quorum.Unobserved {
		penalize(30, "controller quorum not observed (the cell-wide view failed)")
	}
	if missing := quorum.Expected - quorum.Answering; missing > 0 {
		if !quorum.Healthy {
			penalize(60, fmt.Sprintf("controller quorum lost (%d of %d answering)", quorum.Answering, quorum.Expected))
		} else {
			penalize(15*missing, fmt.Sprintf("%d of %d controllers missing", missing, quorum.Expected))
		}
	}
	if notReady := quorum.Answering - quorum.Ready; notReady > 0 {
		penalize(min(10*notReady, 30), fmt.Sprintf("%d members not ready", notReady))
	}
	if summary.Leaders.Authority == "" {
		penalize(40, "no authority leader")
	}
	var critical, warning, info int
	for _, insight := range open {
		if scoredDirectly[insight.Rule] {
			continue
		}
		switch insight.Severity {
		case insights.SeverityCritical:
			critical++
		case insights.SeverityWarning:
			warning++
		default:
			info++
		}
	}
	if critical > 0 {
		penalize(min(25*critical, 50), fmt.Sprintf("%d critical problems", critical))
	}
	if warning > 0 {
		penalize(min(8*warning, 24), fmt.Sprintf("%d warnings", warning))
	}
	if info > 0 {
		penalize(min(2*info, 6), fmt.Sprintf("%d notes", info))
	}
	if len(summary.Versions) > 1 {
		penalize(5, "mixed versions")
	}
	value = max(value, 0)
	status := StatusHealthy
	switch {
	case value < 50:
		status = StatusCritical
	case value < 85:
		status = StatusDegraded
	}
	return Health{Score: value, Status: status, Reasons: reasons}
}

func (cluster staticCluster) Cluster(context.Context, bool) (observability.ClusterSnapshot, error) {
	return cluster.snapshot, nil
}

func (source staticInsights) Current() insights.Evaluation {
	return insights.Evaluation{Insights: source.open, Counts: insights.Count(source.open)}
}

func member(name, version string, leader bool) observability.MemberSnapshot {
	return observability.MemberSnapshot{Member: name, Role: "controller", Ready: true, BuildVersion: version,
		Authority: &observability.AuthorityView{Leader: leader, Ready: true, OwnerID: "0000000000T3V33JGXVEMDPEYF", Epoch: 4},
		NATS:      &observability.NATSView{MetaLeader: "c2", StoreUsedBytes: 10, StoreLimitBytes: 100},
		System: &observability.SystemView{CPUCount: 2, MemTotalBytes: 100, MemAvailBytes: 40,
			Filesystems: []observability.FilesystemView{{Role: "nats", SizeBytes: 1000, AvailBytes: 600}}},
		Placement: &observability.PlacementView{Databases: []observability.DatabaseView{{DatabaseID: "0000000000FFE2BMB99VWR8Y1A",
			DesiredSeats: 2, Serving: 2, Rollout: &observability.RolloutView{OperationID: "00000000000DXENTQMQFS6VPNY", Seats: 2, Completed: 1}}}},
	}
}

func cluster(members ...observability.MemberSnapshot) observability.ClusterSnapshot {
	return observability.ClusterSnapshot{Cell: "gru", Expected: []string{"c1", "c2", "c3"}, Members: members}
}

func DistinctFilesystems(filesystems []FilesystemView) []FilesystemView {
	type identity struct {
		device                            uint64
		size, avail, free, files, freeIno uint64
	}
	index := map[identity]int{}
	out := make([]FilesystemView, 0, len(filesystems))
	for _, filesystem := range filesystems {
		key := identity{device: filesystem.Device}
		if filesystem.Device == 0 {
			key = identity{size: filesystem.SizeBytes, avail: filesystem.AvailBytes, free: filesystem.FreeBytes,
				files: filesystem.Files, freeIno: filesystem.FilesFree}
		}
		if filesystem.SizeBytes == 0 {
			// Unobserved (statfs failed): nothing to double count.
			out = append(out, filesystem)
			continue
		}
		if at, ok := index[key]; ok {
			out[at].Role += ", " + filesystem.Role
			continue
		}
		index[key] = len(out)
		out = append(out, filesystem)
	}
	return out
}

func Count(insights []Insight) Counts {
	var counts Counts
	for _, insight := range insights {
		switch insight.Severity {
		case SeverityCritical:
			counts.Critical++
		case SeverityWarning:
			counts.Warning++
		default:
			counts.Info++
		}
	}
	return counts
}

// Rules whose problem the score already counts from the snapshot.
var scoredDirectly = map[string]bool{"quorum_at_risk": true, "no_leader": true, "member_not_ready": true}

// score derives a deterministic health score. Quorum, leadership and
// readiness come from the snapshot; other open insights subtract by

journal.text:
func NewJournal(config JournalConfig) *Journal {
	if config.QueueSize <= 0 {
		config.QueueSize = DefaultQueueSize
	}
	if config.Capacity <= 0 {
		config.Capacity = DefaultCapacity
	}
	if config.PublishTimeout <= 0 {
		config.PublishTimeout = DefaultPublishTimeout
	}
	if config.Now == nil {
		config.Now = time.Now
	}
	journal := &Journal{config: config, queue: make(chan Decision, config.QueueSize),
		ring: make([]Decision, config.Capacity), ids: map[string]bool{},
		subscribers: map[*subscriber]struct{}{}}
	journal.Attach(config.Sink, config.Archive)
	return journal
}

func (journal *Journal) Attach(sink Sink, archive Archive) {
	if sink == nil && archive == nil {
		return
	}
	journal.storage.Store(&storageHolder{sink: sink, archive: archive})
}

func (journal *Journal) currentStorage() (Sink, Archive) {
	if holder := journal.storage.Load(); holder != nil {
		return holder.sink, holder.archive
	}
	return nil, nil
}

func (journal *Journal) Record(ctx context.Context, decision Decision) string {
	if decision.Region == "" {
		decision.Region = journal.config.Region
	}
	if decision.Actor.Member == "" {
		decision.Actor.Member = journal.config.Member
	}
	decision = decision.Normalize(journal.config.Now())
	// A decision with a caller-chosen ID that is already indexed (an
	// idempotent replay) is indexed and logged once. Its durable copy is
	// queued again unless it is known to be stored, since the first attempt
	// may have been dropped from a full queue or failed to publish; the
	// stream deduplicates a copy that did land by its message ID.
	if fresh, durable := journal.ingest(decision, false); !fresh {
		if !durable {
			journal.enqueue(decision)
		}
		return decision.ID
	}
	journal.recorded.Add(1)
	recordedTotal.Inc()
	if journal.config.Log {
		LogRecorder{}.Record(ctx, decision)
	}
	journal.enqueue(decision)
	return decision.ID
}

func (journal *Journal) enqueue(decision Decision) {
	select {
	case journal.queue <- decision:
		queueDepth.Add(1)
	default:
		journal.dropped.Add(1)
		droppedQueueFull.Inc()
	}
}

func (journal *Journal) Ingest(decision Decision) bool {
	fresh, _ := journal.ingest(decision, true)
	return fresh
}

func (journal *Journal) ingest(decision Decision, durable bool) (bool, bool) {
	journal.mu.Lock()
	defer journal.mu.Unlock()
	if known, seen := journal.ids[decision.ID]; seen {
		if durable && !known {
			journal.ids[decision.ID] = true
		}
		return false, known || durable
	}
	ingestedTotal.Inc()
	capacity := len(journal.ring)
	if journal.size == capacity {
		evicted := journal.ring[journal.start]
		delete(journal.ids, evicted.ID)
		if evicted.Time.After(journal.coveredFrom) {
			journal.coveredFrom = evicted.Time
		}
		journal.ring[journal.start] = decision
		journal.start = (journal.start + 1) % capacity
	} else {
		journal.ring[(journal.start+journal.size)%capacity] = decision
		journal.size++
	}
	journal.ids[decision.ID] = durable
	for subscriber := range journal.subscribers {
		select {
		case subscriber.decisions <- decision:
		default:
		}
	}
	return true, durable
}

func (journal *Journal) snapshot() ([]Decision, time.Time) {
	journal.mu.RLock()
	defer journal.mu.RUnlock()
	decisions := make([]Decision, 0, journal.size)
	for offset := range journal.size {
		decisions = append(decisions, journal.ring[(journal.start+offset)%len(journal.ring)])
	}
	return decisions, journal.coveredFrom
}

func (journal *Journal) Query(ctx context.Context, query Query) (Result, error) {
	query = query.Normalized()
	// The replay flag is read before the snapshot: a replay that ends in
	// between leaves the result conservatively partial, never the reverse.
	replaying := journal.replaying.Load()
	decisions, coveredFrom := journal.snapshot()
	result := Result{}
	seen := make(map[string]struct{}, len(decisions))
	// fresh counts matches newer than coveredFrom. Memory evicts by arrival,
	// not by time, so only those are known to outrank everything evicted.
	fresh := 0
	for _, decision := range decisions {
		if query.Matches(decision) {
			result.Decisions = append(result.Decisions, decision)
			seen[decision.ID] = struct{}{}
			if decision.Time.After(coveredFrom) {
				fresh++
			}
		}
	}
	// While the stream tail is still replaying, memory does not hold the
	// region's history yet.
	if replaying {
		result.Partial = true
	}
	// Older decisions only matter when memory did not fill the page with
	// decisions newer than anything it evicted.
	older := !coveredFrom.IsZero() && (query.Since.IsZero() || query.Since.Before(coveredFrom))
	exhausted := !older
	if older && fresh < query.Limit {
		_, archive := journal.currentStorage()
		if archive == nil {
			result.Partial = true
		} else if complete, reachedFloor := journal.scanArchive(ctx, archive, query, coveredFrom, seen, &result); !complete {
			result.Partial = true
		} else {
			exhausted = reachedFloor
		}
	}
	SortNewestFirst(result.Decisions)
	switch {
	case len(result.Decisions) > query.Limit:
		result.Decisions = result.Decisions[:query.Limit]
		result.Truncated = true
	case len(result.Decisions) == query.Limit && !exhausted:
		// A full page with older history left unsearched may not be all:
		// say so rather than look exhaustive.
		result.Truncated = true
	}
	return result, nil
}

func (query Query) Normalized() Query {
	if query.Limit <= 0 {
		query.Limit = DefaultQueryLimit
	}
	query.Limit = min(query.Limit, MaxQueryLimit)
	query.Regions = slices.Clone(query.Regions)
	for index, region := range query.Regions {
		query.Regions[index] = strings.ToLower(region)
	}
	query.Subject = strings.ToLower(query.Subject)
	return query
}

func (query Query) Matches(decision Decision) bool {
	if len(query.Regions) > 0 && !slices.Contains(query.Regions, decision.Region) {
		return false
	}
	if len(query.Kinds) > 0 && !slices.Contains(query.Kinds, decision.Kind) {
		return false
	}
	if len(query.Actors) > 0 && !slices.ContainsFunc(query.Actors, func(actor string) bool {
		return actor == decision.Actor.Slice || actor == decision.Actor.Slice+"/"+decision.Actor.Member
	}) {
		return false
	}
	if query.SubjectKind != "" && query.SubjectKind != decision.Subject.Kind {
		return false
	}
	if query.SubjectID != "" && query.SubjectID != decision.Subject.ID {
		return false
	}
	if query.Subject != "" && !containsFold(decision.Subject.ID, query.Subject) &&
		!containsFold(decision.Subject.Name, query.Subject) && !containsFold(decision.Summary, query.Subject) {
		return false
	}
	if len(query.Statuses) > 0 && !slices.Contains(query.Statuses, decision.Status) {
		return false
	}
	if query.ParentID != "" && query.ParentID != decision.ParentID {
		return false
	}
	if !query.Since.IsZero() && decision.Time.Before(query.Since) {
		return false
	}
	if !query.Until.IsZero() && !decision.Time.Before(query.Until) {
		return false
	}
	return true
}

func SortNewestFirst(decisions []Decision) {
	slices.SortStableFunc(decisions, func(left, right Decision) int {
		if order := right.Time.Compare(left.Time); order != 0 {
			return order
		}
		return cmp.Compare(right.ID, left.ID)
	})
}

