func (provider *Provider) remote(ctx context.Context, region string) Summary {
	placeholder := Summary{Version: summaryVersion, Region: region,
		Health: Health{Status: StatusUnknown, Reasons: []string{"region not observed"}}}
	if provider.Links == nil {
		placeholder.Reach = decisionlog.RegionNotLinked
		return placeholder
	}
	data, err := provider.Links.Request(ctx, region, SummaryLeaf, summaryRequestPayload)
	if err != nil {
		switch {
		case errors.Is(err, regionlink.ErrNotLinked), errors.Is(err, regionlink.ErrUnknownRegion):
			placeholder.Reach = decisionlog.RegionNotLinked
			placeholder.Health.Reasons = []string{"no cross-region link yet"}
		case errors.Is(err, context.DeadlineExceeded), errors.Is(err, nats.ErrTimeout), errors.Is(err, nats.ErrNoResponders):
			placeholder.Reach = decisionlog.RegionUnreachable
			placeholder.Health.Reasons = []string{"region did not answer"}
		default:
			placeholder.Reach = decisionlog.RegionError
			placeholder.Health.Reasons = []string{"region query failed"}
		}
		return placeholder
	}
	var summary Summary
	if err := json.Unmarshal(data, &summary); err != nil || summary.Version != summaryVersion || summary.Region != region {
		placeholder.Reach = decisionlog.RegionError
		placeholder.Health.Reasons = []string{"region returned an invalid summary"}
		return placeholder
	}
	summary.Local = false
	summary.Reach = decisionlog.RegionOK
	summary.boundTopology()
	// Never trust a region to speak for another one.
	summary.Decisions = slices.DeleteFunc(summary.Decisions, func(decision decisionlog.Decision) bool {
		return decision.Region != region
	})
	return summary
}

func (summary *Summary) boundTopology() {
	summary.Links = summary.Links[:min(len(summary.Links), maxTopologyMembers)]
	summary.TerraBase.WAN = summary.TerraBase.WAN[:min(len(summary.TerraBase.WAN), maxTopologyMembers)]
	summary.Members = summary.Members[:min(len(summary.Members), maxTopologyMembers)]
	summary.Hosts = summary.Hosts[:min(len(summary.Hosts), maxTopologyHosts)]
	summary.Quorum.Missing = summary.Quorum.Missing[:min(len(summary.Quorum.Missing), maxTopologyMembers)]
	summary.Versions = summary.Versions[:min(len(summary.Versions), maxTopologyMembers)]
	summary.boundNodes()
	// Version members are the legacy topology source when Members is
	// absent: bound them across the whole summary, not per version, or 64
	// versions of 64 names would still expand into thousands of
	// controllers and millions of routes. With the missing list (bounded
	// above) at most 2*maxTopologyMembers controllers are meshed.
	budget := maxTopologyMembers
	for index := range summary.Versions {
		members := summary.Versions[index].Members
		keep := min(len(members), budget)
		summary.Versions[index].Members = members[:keep]
		budget -= keep
	}
}

func (summary *Summary) boundNodes() {
	summary.NodesIncomplete = summary.NodesIncomplete || len(summary.Nodes) > maxTopologyMembers
	summary.Nodes = summary.Nodes[:min(len(summary.Nodes), maxTopologyMembers)]
	for index := range summary.Nodes {
		node := &summary.Nodes[index]
		summary.NodesIncomplete = summary.NodesIncomplete || len(node.Services) > maxNodeServices
		node.Services = node.Services[:min(len(node.Services), maxNodeServices)]
		node.Backends = node.Backends[:min(len(node.Backends), maxNodeBackends)]
		node.Fence = node.Fence[:min(len(node.Fence), maxNodeBackends)]
		if node.Resources != nil {
			node.Resources.Filesystems = node.Resources.Filesystems[:min(len(node.Resources.Filesystems), 37)]
		}
	}
}

func (provider *Provider) Reachability(context.Context) []insights.RegionReach {
	if provider.LinkProbes == nil {
		return nil
	}
	var out []insights.RegionReach
	for _, probe := range provider.LinkProbes() {
		state := probe.Reach
		if state != decisionlog.RegionOK && state != decisionlog.RegionUnreachable && state != decisionlog.RegionNotLinked {
			state = decisionlog.RegionError
		}
		reach := insights.RegionReach{Region: probe.Region, State: state, LastSeen: probe.LastSuccessAt}
		if probe.Reach == decisionlog.RegionOK {
			reach.WAN, reach.Detail = probe.WAN, probe.Detail
		}
		out = append(out, reach)
	}
	return out
}

func Serve(ctx context.Context, conn *nats.Conn, cell string, provider *Provider) (*nats.Subscription, error) {
	if conn == nil || provider == nil {
		return nil, errors.New("region summary responder requires a connection and a provider")
	}
	subject, err := protocol.ObservabilitySubject(cell, SummaryLeaf)
	if err != nil {
		return nil, err
	}
	subscription, err := conn.QueueSubscribe(subject, "regionview", func(message *nats.Msg) {
		// Peer regions reach this subject over the interregion contract, so
		// only the exact versioned summary request is answered.
		if message.Reply == "" || !validSummaryRequest(message.Data) {
			return
		}
		answerCtx, cancel := context.WithTimeout(observability.ContinueTrace(ctx, message.Header.Get("traceparent")), 2*time.Second)
		defer cancel()
		data, err := json.Marshal(provider.Local(answerCtx))
		if err != nil || int64(len(data)) > conn.MaxPayload() {
			return
		}
		_ = message.Respond(data)
	})
	if err != nil {
		return nil, err
	}
	context.AfterFunc(ctx, func() { _ = subscription.Unsubscribe() })
	return subscription, nil
}

func validSummaryRequest(data []byte) bool {
	var request summaryRequest
	return len(data) <= maxRequestBytes && protocol.DecodeStrict(data, &request, maxRequestBytes) == nil &&
		request.Version == summaryVersion
}

func (provider *Provider) Probe(ctx context.Context, region string) Summary {
	summary := provider.remote(ctx, region)
	if summary.Reach == decisionlog.RegionOK && (summary.ObservedAt.IsZero() ||
		provider.now().Sub(summary.ObservedAt) > 2*time.Minute || summary.ObservedAt.After(provider.now().Add(time.Minute))) {
		summary.Reach = decisionlog.RegionError
		summary.Health = Health{Status: StatusUnknown, Reasons: []string{"region answered with stale telemetry"}}
	}
	return summary
}

links.text:
func New(local string, conn *nats.Conn, configured []string, timeout time.Duration) (*Links, error) {
	token, err := protocol.RegionToken(local)
	if err != nil {
		return nil, err
	}
	if timeout <= 0 {
		timeout = DefaultTimeout
	}
	links := &Links{local: token, timeout: timeout, conns: map[string]*nats.Conn{}}
	links.regions = append(links.regions, token)
	for _, region := range configured {
		if regionToken, err := protocol.RegionToken(region); err == nil && regionToken != protocol.GlobalScope &&
			!slices.Contains(links.regions, regionToken) {
			links.regions = append(links.regions, regionToken)
		}
	}
	slices.Sort(links.regions[1:])
	if conn != nil {
		links.conns[token] = conn
	}
	return links, nil
}

func (links *Links) Link(region string, conn *nats.Conn) error {
	token, err := protocol.RegionToken(region)
	if err != nil || token == protocol.GlobalScope {
		return protocol.ErrInvalidSubjectToken
	}
	links.mu.Lock()
	defer links.mu.Unlock()
	if !slices.Contains(links.regions, token) {
		links.regions = append(links.regions, token)
		slices.Sort(links.regions[1:])
	}
	if conn == nil {
		delete(links.conns, token)
	} else {
		links.conns[token] = conn
	}
	return nil
}

func (links *Links) Regions() []string {
	links.mu.RLock()
	defer links.mu.RUnlock()
	return slices.Clone(links.regions)
}

func (links *Links) Request(ctx context.Context, region, leaf string, payload []byte) ([]byte, error) {
	region = strings.ToLower(region)
	links.mu.RLock()
	conn, linked := links.conns[region]
	configured := slices.Contains(links.regions, region)
	links.mu.RUnlock()
	if !configured {
		return nil, ErrUnknownRegion
	}
	if !linked {
		return nil, ErrNotLinked
	}
	subject, err := protocol.ObservabilitySubject(region, leaf)
	if err != nil {
		return nil, err
	}
	// Always bound the request by the link timeout; an earlier caller
	// deadline still wins, a later one does not stretch it.
	ctx, cancel := context.WithTimeout(ctx, links.timeout)
	defer cancel()
	message, err := conn.RequestMsgWithContext(ctx, &nats.Msg{Subject: subject, Data: payload, Header: observability.TraceHeader(ctx, nil)})
	if err != nil {
		return nil, err
	}
	return message.Data, nil
}

func (static Static) Request(ctx context.Context, region, leaf string, payload []byte) ([]byte, error) {
	if static.Handler == nil {
		return nil, ErrNotLinked
	}
	return static.Handler(ctx, region, leaf, payload)
}

func CanonicalRegion(region string) (string, error) {
	if region == "" || len(region) > 63 {
		return "", fmt.Errorf("%w: region length is out of bounds", ErrInvalidSubjectToken)
	}
	region = strings.ToUpper(region)
	if region == "GLOBAL" {
		return region, nil
	}
	previousHyphen := true
	for _, character := range region {
		if character == '-' {
			if previousHyphen {
				return "", ErrInvalidSubjectToken
			}
			previousHyphen = true
			continue
		}
		if character < 'A' || character > 'Z' {
			if character < '0' || character > '9' {
				return "", ErrInvalidSubjectToken
			}
		}
		previousHyphen = false
	}
	if previousHyphen {
		return "", ErrInvalidSubjectToken
	}
	return region, nil
}

func RegionToken(region string) (string, error) {
	canonical, err := CanonicalRegion(region)
	if err != nil {
		return "", err
	}
	return strings.ToLower(canonical), nil
}

func RegionalRoot(region string) (string, error) {
	token, err := RegionToken(region)
	if err != nil || token == GlobalScope {
		return "", ErrInvalidSubjectToken
	}
	return SubjectRoot + "." + token, nil
}

func ObservabilitySubject(region, leaf string) (string, error) {
	return regionalSubject(region, "obs", leaf)
}

func ValidateSubjectToken(token string) error {
	if !validToken(token) {
		return ErrInvalidSubjectToken
	}
	return nil
}

func regionalSubject(region, family, leaf string) (string, error) {
	if err := ValidateSubjectToken(leaf); err != nil {
		return "", err
	}
	root, err := RegionalRoot(region)
	if err != nil {
		return "", err
	}
	return root + "." + family + "." + leaf, nil
}

insights.text:
func NewEngine(config Config) *Engine {
	if config.Interval <= 0 {
		config.Interval = DefaultInterval
	}
	if config.Now == nil {
		config.Now = time.Now
	}
	config.Region = strings.ToLower(config.Region)
	config.Thresholds = config.Thresholds.withDefaults()
	rules := config.Rules
	if rules == nil {
		rules = DefaultRules()
	}
	return &Engine{config: config, rules: rules, conditions: map[string]time.Time{}, owners: map[string]string{},
		open: map[string]Insight{}, subscribers: map[*changeSubscriber]struct{}{}}
}

func (engine *Engine) gather(ctx context.Context, now time.Time) (*Inputs, []string) {
	config := engine.config
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	inputs := &Inputs{Now: now, Region: config.Region, Thresholds: config.Thresholds, History: config.History}
	var unavailable []string
	fail := func(name string) { unavailable = append(unavailable, name) }
	if config.Cluster != nil {
		if cluster, err := config.Cluster.Cluster(ctx, false); err == nil {
			inputs.Cluster = &cluster
		} else {
			fail("cluster")
		}
	}
	if inputs.Cluster == nil && config.Local != nil {
		if snapshot, err := config.Local.Snapshot(ctx, false); err == nil {
			inputs.Cluster = &observability.ClusterSnapshot{Cell: snapshot.Cell, ObservedAt: snapshot.ObservedAt,
				Members: []observability.MemberSnapshot{snapshot}}
		} else {
			fail("snapshot")
		}
	}
	if config.Decisions != nil {
		// Only the repeated-hold rule reads decisions: ask for exactly the
		// holds in its window, and treat an incomplete answer as no input
		// rather than as fewer holds.
		result, err := config.Decisions.Query(ctx, decisionlog.Query{Regions: []string{config.Region},
			Kinds: []decisionlog.Kind{decisionlog.KindHeld}, Since: now.Add(-decisionWindow), Limit: maxDecisions})
		switch {
		case err != nil || result.Truncated || result.Partial:
			fail("decisions")
		default:
			inputs.Decisions = result.Decisions
		}
	}
	check := func(name string, err error) {
		if err != nil {
			fail(name)
		}
	}
	var err error
	if config.Rollouts != nil {
		inputs.Rollouts, err = config.Rollouts.Rollouts(ctx)
		check("rollouts", err)
	}
	if config.Volumes != nil {
		inputs.Volumes, err = config.Volumes.Volumes(ctx)
		check("volumes", err)
	}
	if config.Certificates != nil {
		inputs.Certificates, err = config.Certificates.Certificates(ctx)
		check("certificates", err)
	}
	if config.NetBird != nil {
		inputs.Peers, err = config.NetBird.Peers(ctx)
		check("netbird", err)
	}
	if config.Autoscalers != nil {
		inputs.Autoscalers, err = config.Autoscalers.Autoscalers(ctx)
		check("autoscalers", err)
	}
	if config.Budgets != nil {
		inputs.Budgets, err = config.Budgets.Budgets(ctx)
		check("budgets", err)
	}
	if config.Reachability != nil {
		inputs.Reachability = config.Reachability.Reachability(ctx)
	}
	if config.Holds != nil {
		inputs.Holds = config.Holds.Holds(now)
	}
	if config.OCIResources != nil {
		inputs.OCIResources, err = config.OCIResources.OCIResources(ctx)
		check("oci_resources", err)
	}
	if inputs.Cluster != nil {
		// A member that did not answer was not observed: its insights stay
		// open rather than resolve.
		for _, member := range inputs.Cluster.Missing {
			fail("member " + member)
		}
		sections := map[string]bool{}
		var memberSections []string
		for _, member := range inputs.Cluster.Members {
			for section := range member.Errors {
				sections[section] = true
				// Per-member rules name the member's own section, so one
				// member's failure does not hold every member's insights.
				memberSections = append(memberSections, "member "+member.Member+" section "+section)
			}
		}
		for _, section := range slices.Sorted(maps.Keys(sections)) {
			fail("section " + section)
		}
		slices.Sort(memberSections)
		unavailable = append(unavailable, memberSections...)
	}
	return inputs, unavailable
}

func (engine *Engine) Evaluate(ctx context.Context) Evaluation {
	now := engine.config.Now().UTC()
	inputs, unavailable := engine.gather(ctx, now)
	engine.mu.Lock()
	defer engine.mu.Unlock()
	inputs.conditions = engine.conditions
	inputs.touched = map[string]struct{}{}
	inputs.owners = engine.owners
	found := map[string]Insight{}
	for _, rule := range engine.rules {
		inputs.rule = rule.Name
		for _, insight := range rule.Evaluate(inputs) {
			if insight.Rule == "" {
				insight.Rule = rule.Name
			}
			if insight.Key == "" {
				insight.Key = insight.Rule + ":" + insight.Entity.Kind + ":" + insight.Entity.ID
			}
			if insight.Region == "" {
				insight.Region = engine.config.Region
			}
			insight.Key = entityid.Derive("insight", insight.Region, insight.Key)
			if insight.Entity.Region == "" {
				insight.Entity.Region = insight.Region
			}
			if existing, duplicate := found[insight.Key]; duplicate && existing.Severity.Rank() >= insight.Severity.Rank() {
				continue
			}
			found[insight.Key] = insight
		}
	}
	blind := blindRules(unavailable)
	// An untouched condition timer resets unless the rule that owns it could
	// not read its inputs: a blind rule keeps its duration-gated timers,
	// while a rule that looked and saw health starts afresh next time.
	for key := range engine.conditions {
		if _, touched := inputs.touched[key]; !touched && !blind[engine.owners[key]] {
			delete(engine.conditions, key)
			delete(engine.owners, key)
		}
	}
	var changes []Change
	for _, key := range slices.Sorted(maps.Keys(found)) {
		insight := found[key]
		insight.LastSeen = now
		previous, wasOpen := engine.open[key]
		switch {
		case !wasOpen:
			insight.FirstSeen = now
			changes = append(changes, Change{Type: ChangeOpened, Time: now, Insight: insight})
		default:
			insight.FirstSeen = previous.FirstSeen
			if insight.Severity.Rank() > previous.Severity.Rank() {
				changes = append(changes, Change{Type: ChangeEscalated, Time: now, Insight: insight})
			}
		}
		engine.open[key] = insight
	}
	for _, key := range slices.Sorted(maps.Keys(engine.open)) {
		if _, still := found[key]; !still {
			if insightBlind(engine.open[key], blind, unavailable) {
				// Not observed this pass: keep it open until a successful
				// observation clears it.
				continue
			}
			resolved := engine.open[key]
			resolved.LastSeen = now
			changes = append(changes, Change{Type: ChangeResolved, Time: now, Insight: resolved})
			delete(engine.open, key)
		}
	}
	insights := slices.Collect(maps.Values(engine.open))
	Rank(insights)
	engine.current = Evaluation{At: now, Insights: insights, Counts: Count(insights), Unavailable: unavailable}
	for _, change := range changes {
		engine.changes = append(engine.changes, change)
		for subscriber := range engine.subscribers {
			select {
			case subscriber.changes <- change:
			default:
			}
		}
	}
	if overflow := len(engine.changes) - changeCapacity; overflow > 0 {
		engine.droppedThrough = engine.changes[overflow-1].Time
		engine.changes = slices.Delete(engine.changes, 0, overflow)
	}
	return engine.current
}

func regionUnreachable(inputs *Inputs) []Insight {
	var out []Insight
	for _, reach := range inputs.Reachability {
		wanUnhealthy := reach.State == decisionlog.RegionOK && reach.WAN == regionlink.WANFailed
		if reach.State != decisionlog.RegionUnreachable && reach.State != decisionlog.RegionError && !wanUnhealthy {
			continue
		}
		key := "region:" + reach.Region
		if wanUnhealthy {
			key = "region-wan:" + reach.Region
		}
		held := inputs.Since(key)
		if held < inputs.Thresholds.RegionUnreachable {
			continue
		}
		title := "Region " + strings.ToUpper(reach.Region) + " is unreachable"
		evidence := "Unreachable for"
		why := fmt.Sprintf("%s has not answered cross-region queries for %s.", strings.ToUpper(reach.Region), roundDuration(held))
		if wanUnhealthy {
			title = "TerraBase WAN to " + strings.ToUpper(reach.Region) + " is " + reach.WAN
			evidence = "Unhealthy for"
			why = reach.Detail
		}
		out = append(out, Insight{Severity: SeverityCritical, Score: held.Seconds(), Region: reach.Region,
			Title: title, Why: why,
			Entity: Entity{Kind: "region", ID: reach.Region, Region: reach.Region, Href: "/regions/" + reach.Region},
			Evidence: []Evidence{{Label: evidence, Value: held.Seconds(), Unit: "s", Comparison: "<",
				Threshold: threshold(inputs.Thresholds.RegionUnreachable.Seconds())}},
			Actions: []Action{{Label: "Open the global view", Href: "/regions"}}})
	}
	return out
}

capacity.text:
func (reading *Reading) Fresh(now time.Time) bool {
	return reading != nil && !reading.ObservedAt.IsZero() && !reading.ObservedAt.After(now) && now.Sub(reading.ObservedAt) <= ResourceFreshFor
}

func fillNodeCapacity(summary *Summary) {
	capacity := Capacity{StoreUsedBytes: summary.Capacity.StoreUsedBytes, StoreLimitBytes: summary.Capacity.StoreLimitBytes,
		Partial: len(summary.Nodes) == 0}
	seen := map[string]bool{}
	for _, node := range summary.Nodes {
		if seen[node.Name] {
			continue
		}
		seen[node.Name] = true
		resources := node.Resources
		if resources == nil {
			capacity.Partial = true
			continue
		}
		capacity.Partial = capacity.Partial || resources.Pending || resources.Incomplete
		if resources.CPUCores.Fresh(summary.ObservedAt) && resources.CPU.Fresh(summary.ObservedAt) &&
			resources.CPUCores.ObservedAt.Equal(resources.CPU.ObservedAt) {
			capacity.CPUs += int(resources.CPUCores.Value)
			capacity.CPUUtilization += resources.CPU.Value * resources.CPUCores.Value
		} else {
			capacity.Partial = true
		}
		if resources.MemoryBytes.Fresh(summary.ObservedAt) && resources.MemoryUsedBytes.Fresh(summary.ObservedAt) &&
			resources.MemoryBytes.ObservedAt.Equal(resources.MemoryUsedBytes.ObservedAt) {
			capacity.MemoryBytes += uint64(resources.MemoryBytes.Value)
			capacity.MemoryUsedBytes += uint64(resources.MemoryUsedBytes.Value)
		} else {
			capacity.Partial = true
		}
		if len(resources.Filesystems) == 0 {
			capacity.Partial = true
		}
		for _, filesystem := range resources.Filesystems {
			if filesystem.SizeBytes.Fresh(summary.ObservedAt) && filesystem.UsedBytes.Fresh(summary.ObservedAt) &&
				filesystem.SizeBytes.ObservedAt.Equal(filesystem.UsedBytes.ObservedAt) {
				capacity.DiskBytes += uint64(filesystem.SizeBytes.Value)
				capacity.DiskUsedBytes += uint64(filesystem.UsedBytes.Value)
			} else {
				capacity.Partial = true
			}
		}
	}
	if capacity.CPUs > 0 {
		capacity.CPUUtilization /= float64(capacity.CPUs)
	}
	summary.Capacity = capacity
}

